import Button from "@mui/material/Button";
import Stack from "@mui/material/Stack";
import QuackNet from "./QuackNet";
import {styled} from '@mui/material/styles'
import Paper from '@mui/material/Paper'

import React from "react"

const BootstrapButton = styled(Button)({
  boxShadow: 'none',
  textTransform: 'none',
  fontSize: 16,
  color: '#061213',
  fontWeight: 'bold',
  padding: '6px 12px',
  lineHeight: 1.5,
  fontFamily: [
    'Poppins'
  ]
});

const FilledButton = styled(Button)({
  boxShadow: 'none',
  textTransform: 'none',
  fontSize: 16,
  padding: '6px 20px',
  border: '1px solid',
  lineHeight: 1.5,
  backgroundColor: '#1F5960',
  borderColor: '#1F5960',
  fontFamily: [
    'Poppins'
  ].join(','),
  '&:hover': {
    backgroundColor: '#173539',
    borderColor: '#173539',
    boxShadow: 'none',
  },
  '&:active': {
    boxShadow: 'none',
    backgroundColor: '#173539',
    borderColor: '#173539',
  },
  '&:focus': {
    boxShadow: '0 0 0 0.2rem rgba(0,123,255,.5)',
  },
});

function NavigationBar() {
  return (
      // <Stack direction="row" spacing={1} sx= {{ justifyContent: "space-between", alignItems: "center", padding: "1vw", backgroundColor: "#99D6DE"}}>
      //     <QuackNet />
      //   <BootstrapButton variant="text">Link Account</BootstrapButton>
      //   <BootstrapButton variant="text">Games</BootstrapButton>
      //   <BootstrapButton variant="text">About COMS</BootstrapButton>
      //   <FilledButton variant="contained">Profile</FilledButton>
      // </Stack>
    <Router></Router>
  );
}

export default NavigationBar;
